 internal static void Watch(Control c){if(c is TextBoxBase||IsDynamic(c))return;if(!watched.Contains(c)){watched.Add(c);originals[c]=c.Text;c.TextChanged+=delegate{if(!applying){originals[c]=c.Text;Translate(c);}};c.ControlAdded+=delegate(object sender,ControlEventArgs a){Watch(a.Control);};c.Disposed+=delegate{watched.Remove(c);originals.Remove(c);};}Translate(c);foreach(Control child in Children(c))Watch(child);}
 static bool applying;static void Translate(Control c){if(c.IsDisposed||c is TextBoxBase||c is ComboBox||IsDynamic(c))return;bool previous=applying;applying=true;try{string original; if(originals.TryGetValue(c,out original))c.Text=T(original);var nav=c as LuxuryNavButton;if(nav!=null){nav.Title=T(nav.AccessibleName);nav.Invalidate();}var pill=c as StatusPill;if(pill!=null){pill.StatusText=T(pill.StatusText);pill.Invalidate();}if(c.Name=="trafficStrip")c.RightToLeft=RightToLeft.No;else{var direction=Farsi?RightToLeft.Yes:RightToLeft.No;if(!(c is Form && ((Form)c).Visible)&&c.RightToLeft!=direction)c.RightToLeft=direction;}var font=(c.Name=="dialAction"||c.Font.Name.Contains("Black"))?Theme.Display(c.Font.Size):Theme.Font(c.Font.Size,c.Font.Style);if(c.Font.Name!=font.Name||Math.Abs(c.Font.Size-font.Size)>.1f||c.Font.Style!=font.Style)c.Font=font;else font.Dispose();}finally{applying=previous;}}
