 static void Repaint(Control c,Dictionary<int,Color> colors){Color n;if(colors.TryGetValue(c.BackColor.ToArgb(),out n))c.BackColor=n;if(colors.TryGetValue(c.ForeColor.ToArgb(),out n))c.ForeColor=n;Translate(c);c.Invalidate();foreach(Control child in Children(c))if(!child.IsDisposed)Repaint(child,colors);}
